class Student:
    """A user-defined data type that groups related data."""

    def __init__(self, name, roll_no, marks):
        self.name = name
        self.roll_no = roll_no
        self.marks = marks

    def percentage(self):
        return sum(self.marks) / len(self.marks)

    def __str__(self):
        return f"Student({self.name}, Roll {self.roll_no})"


