        self.data = data
        self.next = None


def build(values):
    head = None
    tail = None
    for value in values:
        node = Node(value)
        if head is None:
            head = tail = node
        else:
            tail.next = node
            tail = node
    return head


def search(head, key):
    """Return the 0-based position of key, or -1 if absent."""
    position = 0
    current = head
    while current is not None:
        if current.data == key:
            return position
        current = current.next
        position += 1
    return -1


